import type { PlayerClientRuntimeConfig } from './interface';

export interface PlayerClientConfig extends PlayerClientRuntimeConfig {
  // TODO If we have configs generated by client?
}

function getConfig() {
  if (typeof window === 'undefined') {
    return {};
  }

  return window['CLIENT_CONFIG'];
}

// 默认的配置
const DEFAULT_CLIENT_CONFIG = {
  appEnv: 'production',
  appEdition: 'createra',
};

export const clientConfig: PlayerClientConfig = Object.assign(
  DEFAULT_CLIENT_CONFIG,
  getConfig(),
);
